description:
Build and check the data of a `WM_COPYDATA` message (lesson 4.04) that asks a running editor to open a file. On Windows the path is UTF-16, `wchar_t`; here it is `std::u16string`, which has the same 2-byte characters on every compiler.

```cpp
struct CopyData { std::uint64_t type; std::vector<std::uint8_t> bytes; };
constexpr std::uint64_t OPEN_FILE{ 1 };

CopyData openFileMessage(const std::u16string& path);
std::optional<std::u16string> readOpenFile(const CopyData& message);
```

- **openFileMessage** puts the path's characters into `bytes`, each as 2 little-endian bytes, followed by a terminating zero character (2 zero bytes), with `type` `OPEN_FILE`.
- **readOpenFile** accepts only messages that **any** program could have sent, so it checks everything: `type` must be `OPEN_FILE`; the size must be even and at least 4 bytes (one character and the terminator); the last character must be the terminating zero; no other character may be zero; the path may be at most 32 767 characters. It returns the path without the terminator, or `std::nullopt`.

starter.solution.cpp:
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct CopyData { std::uint64_t type; std::vector<std::uint8_t> bytes; };
constexpr std::uint64_t OPEN_FILE{ 1 };

CopyData openFileMessage(const std::u16string& path) { return { OPEN_FILE, {} }; }
std::optional<std::u16string> readOpenFile(const CopyData& message) { return std::nullopt; }

solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct CopyData { std::uint64_t type; std::vector<std::uint8_t> bytes; };
constexpr std::uint64_t OPEN_FILE{ 1 };

CopyData openFileMessage(const std::u16string& path)
{
    CopyData m{ OPEN_FILE, {} };
    for (char16_t c : path)
    {
        m.bytes.push_back(static_cast<std::uint8_t>(c & 0xFF));
        m.bytes.push_back(static_cast<std::uint8_t>(c >> 8));
    }
    m.bytes.push_back(0);
    m.bytes.push_back(0);
    return m;
}

std::optional<std::u16string> readOpenFile(const CopyData& message)
{
    const auto& b{ message.bytes };
    if (message.type != OPEN_FILE || b.size() < 4 || b.size() % 2 != 0) return std::nullopt;
    const std::size_t chars{ b.size() / 2 };
    if (chars - 1 > 32767) return std::nullopt;
    std::u16string path;
    for (std::size_t i{ 0 }; i < chars; ++i)
    {
        const auto c{ static_cast<char16_t>(b[2 * i] | (b[2 * i + 1] << 8)) };
        const bool last{ i + 1 == chars };
        if (last != (c == 0)) return std::nullopt;
        if (!last) path += c;
    }
    return path;
}

unitTests:
TEST("building the message") {
    const CopyData m{ openFileMessage(u"C:\\a.x") };
    CHECK_EQ(m.type, OPEN_FILE);
    CHECK_EQ(m.bytes.size(), 14u);
    CHECK(m.bytes[0] == 'C' && m.bytes[1] == 0);
    CHECK(m.bytes[12] == 0 && m.bytes[13] == 0);
    const CopyData e{ openFileMessage(u"\u00e9") };
    CHECK(e.bytes[0] == 0xE9 && e.bytes[1] == 0x00);
}
TEST("round trip") {
    const std::u16string path{ u"C:\\Projects\\caf\u00e9\\demo.xproj" };
    CHECK(readOpenFile(openFileMessage(path)) == std::optional<std::u16string>{ path });
}
TEST("rejecting anything odd") {
    CopyData wrongType{ openFileMessage(u"a") };
    wrongType.type = 2;
    CHECK(!readOpenFile(wrongType).has_value());
    CHECK(!readOpenFile({ OPEN_FILE, {} }).has_value());
    CHECK(!readOpenFile({ OPEN_FILE, { 0, 0 } }).has_value());
    CHECK(!readOpenFile({ OPEN_FILE, { 'a', 0, 0 } }).has_value());
    CHECK(!readOpenFile({ OPEN_FILE, { 'a', 0, 'b', 0 } }).has_value());
    CHECK(!readOpenFile({ OPEN_FILE, { 'a', 0, 0, 0, 'b', 0, 0, 0 } }).has_value());
    const CopyData longest{ openFileMessage(std::u16string(32767, u'x')) };
    CHECK(readOpenFile(longest).has_value());
    const CopyData tooLong{ openFileMessage(std::u16string(32768, u'x')) };
    CHECK(!readOpenFile(tooLong).has_value());
}

